arguments.command:
curl -s "https://echo-agent-platform.zhouyating.workers.dev/history?threadId=arbitration&limit=100" -H "X-API-Key: echo-a…-key" | python3 -c "
import json, sys, datetime
d = json.load(sys.stdin)
msgs = d.get('messages', [])

# Categorize properly
# Recent activity split by content type
stats = {}
for m in msgs:
    c = m.get('content', '')
    ts = m['timestamp']/1000
    t = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    # Bucket by day
    day = t.date().isoformat()
    if c.strip() == '**[Heartbeat 23:50 UTC]**':
        kind = 'stub'
    elif c.startswith('**[Heartbeat') or 'B4-E2校准' in c or 'CPL-004' in c:
        kind = 'cron-heartbeat'
    elif '心跳确认' in c and 'C通道' in c:
        kind = 'agent-confirm-c'
    elif '心跳确认' in c:
        kind = 'agent-confirm'
    elif '【' in c[:5] or '测试' in c[:5] or '啊啊啊' in c[:5]:
        kind = 'discussion'
    else:
        kind = 'other'
    stats.setdefault(day, {}).setdefault(kind, 0)
    stats[day][kind] += 1

for day in sorted(stats):
    print(day, stats[day])
"
